.error-display {
          display: flex;
          align-items: flex-start;
          gap: var(--spacing-md);
          padding: var(--spacing-lg);
          background-color: rgba(219, 76, 64, 0.1);
          border: 1px solid var(--color-error);
          border-radius: var(--radius-lg);
          border-left: 4px solid var(--color-error);
          position: relative;
        }

        .error-display--compact {
          padding: var(--spacing-md);
          align-items: center;
        }

        /* Error type variations */
        .error-display--upload {
          border-color: var(--color-error);
          border-left-color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.08);
        }

        .error-display--validation {
          border-color: var(--color-warning);
          border-left-color: var(--color-warning);
          background-color: rgba(239, 189, 117, 0.15);
        }

        .error-display--network {
          border-color: var(--color-error);
          border-left-color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.08);
        }

        .error-display--generic {
          border-color: var(--color-error);
          border-left-color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.08);
        }

        /* Icon container */
        .error-icon-container {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 48px;
          height: 48px;
          min-width: 48px;
          background-color: var(--color-background);
          border-radius: var(--radius-full);
          border: 2px solid var(--color-error);
        }

        .error-display--validation .error-icon-container {
          border-color: var(--color-warning);
        }

        .error-display--compact .error-icon-container {
          width: 36px;
          height: 36px;
          min-width: 36px;
        }

        .error-icon {
          font-size: var(--font-size-xl);
          line-height: 1;
        }

        .error-display--compact .error-icon {
          font-size: var(--font-size-lg);
        }

        /* Content area */
        .error-content {
          flex: 1;
          display: flex;
          flex-direction: column;
          gap: var(--spacing-sm);
          min-width: 0;
        }

        .error-display--compact .error-content {
          gap: var(--spacing-xs);
        }

        /* Title */
        .error-title {
          margin: 0;
          font-size: var(--font-size-lg);
          font-weight: 600;
          color: var(--color-error);
        }

        .error-display--validation .error-title {
          color: var(--color-warning-dark, #c99a40);
        }

        /* Message */
        .error-message {
          margin: 0;
          font-size: var(--font-size-base);
          color: var(--color-text);
          line-height: 1.5;
        }

        .error-display--compact .error-message {
          font-size: var(--font-size-sm);
        }

        /* Details (expandable) */
        .error-details {
          margin-top: var(--spacing-xs);
        }

        .error-details-summary {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
          cursor: pointer;
          user-select: none;
        }

        .error-details-summary:hover {
          color: var(--color-text);
        }

        .error-details-content {
          margin: var(--spacing-sm) 0 0 0;
          padding: var(--spacing-md);
          background-color: var(--color-background);
          border-radius: var(--radius-sm);
          font-size: var(--font-size-xs);
          font-family: monospace;
          color: var(--color-text-secondary);
          overflow-x: auto;
          white-space: pre-wrap;
          word-break: break-word;
          max-height: 150px;
          overflow-y: auto;
        }

        /* Hint text */
        .error-hint {
          margin: 0;
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
          font-style: italic;
        }

        /* Action buttons */
        .error-actions {
          display: flex;
          gap: var(--spacing-sm);
          margin-top: var(--spacing-sm);
          flex-wrap: wrap;
        }

        .error-display--compact .error-actions {
          margin-top: 0;
          margin-left: auto;
        }

        /* Retry button */
        .error-retry-btn {
          display: inline-flex;
          align-items: center;
          gap: var(--spacing-xs);
          padding: var(--spacing-sm) var(--spacing-lg);
          border: none;
          border-radius: var(--radius-md);
          background-color: var(--color-error);
          color: var(--color-text-light);
          font-size: var(--font-size-sm);
          font-weight: 600;
          cursor: pointer;
          transition: all var(--transition-fast);
          min-height: 40px;
        }

        .error-retry-btn:hover {
          background-color: #c43830;
          transform: translateY(-1px);
        }

        .error-retry-btn:active {
          transform: translateY(0);
        }

        .error-retry-btn:focus-visible {
          outline: 2px solid var(--color-error);
          outline-offset: 2px;
        }

        .retry-icon {
          font-size: var(--font-size-lg);
          display: inline-block;
          transition: transform var(--transition-fast);
        }

        .error-retry-btn:hover .retry-icon {
          transform: rotate(-45deg);
        }

        /* Dismiss button */
        .error-dismiss-btn {
          display: inline-flex;
          align-items: center;
          padding: var(--spacing-sm) var(--spacing-lg);
          border: 1px solid var(--color-border);
          border-radius: var(--radius-md);
          background-color: var(--color-surface);
          color: var(--color-text-secondary);
          font-size: var(--font-size-sm);
          font-weight: 500;
          cursor: pointer;
          transition: all var(--transition-fast);
          min-height: 40px;
        }

        .error-dismiss-btn:hover {
          border-color: var(--color-text-secondary);
          color: var(--color-text);
        }

        .error-dismiss-btn:focus-visible {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        /* Close button (top-right corner) */
        .error-close-btn {
          position: absolute;
          top: var(--spacing-sm);
          right: var(--spacing-sm);
          display: flex;
          align-items: center;
          justify-content: center;
          width: 28px;
          height: 28px;
          padding: 0;
          border: none;
          border-radius: var(--radius-full);
          background-color: transparent;
          color: var(--color-text-secondary);
          font-size: var(--font-size-base);
          cursor: pointer;
          transition: all var(--transition-fast);
        }

        .error-close-btn:hover {
          background-color: rgba(219, 76, 64, 0.2);
          color: var(--color-error);
        }

        .error-close-btn:focus-visible {
          outline: 2px solid var(--color-error);
          outline-offset: 2px;
        }

        /* Responsive adjustments */
        @media (max-width: 480px) {
          .error-display {
            flex-direction: column;
            align-items: stretch;
            padding: var(--spacing-md);
          }

          .error-display--compact {
            flex-direction: row;
            flex-wrap: wrap;
          }

          .error-icon-container {
            align-self: center;
            margin-bottom: var(--spacing-sm);
          }

          .error-display--compact .error-icon-container {
            align-self: flex-start;
            margin-bottom: 0;
          }

          .error-content {
            text-align: center;
          }

          .error-display--compact .error-content {
            text-align: left;
          }

          .error-actions {
            justify-content: center;
          }

          .error-display--compact .error-actions {
            width: 100%;
            margin-top: var(--spacing-sm);
            margin-left: 0;
          }

          .error-close-btn {
            position: static;
            align-self: flex-end;
            margin-bottom: var(--spacing-sm);
          }
        }

        /* Touch device adjustments */
        @media (hover: none) and (pointer: coarse) {
          .error-retry-btn,
          .error-dismiss-btn {
            min-height: 44px;
            padding: var(--spacing-md) var(--spacing-lg);
          }

          .error-close-btn {
            width: 44px;
            height: 44px;
          }
        }

        /* Reduced motion preference */
        @media (prefers-reduced-motion: reduce) {
          .error-retry-btn:hover {
            transform: none;
          }

          .error-retry-btn:hover .retry-icon {
            transform: none;
          }
        }

        /* High contrast mode */
        @media (prefers-contrast: high) {
          .error-display {
            border-width: 2px;
            border-left-width: 6px;
          }

          .error-retry-btn {
            border: 2px solid currentColor;
          }
        }

.file-upload {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-sm);
        }

        .file-upload-label {
          font-size: var(--font-size-base);
          font-weight: 600;
          color: var(--color-text);
        }

        .file-upload-zone {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: var(--spacing-xl) var(--spacing-lg);
          min-height: 150px;
          border: 2px dashed var(--color-border);
          border-radius: var(--radius-lg);
          background-color: var(--color-surface);
          cursor: pointer;
          transition: border-color var(--transition-fast),
            background-color var(--transition-fast);
        }

        .file-upload-zone:hover:not(.file-upload-zone--disabled) {
          border-color: var(--color-primary);
          background-color: var(--color-hover);
        }

        .file-upload-zone:focus-visible {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        .file-upload-zone--drag-over {
          border-color: var(--color-primary);
          background-color: var(--color-active);
          border-style: solid;
        }

        .file-upload-zone--has-file {
          border-color: var(--color-success);
          border-style: solid;
        }

        .file-upload-zone--error {
          border-color: var(--color-error);
        }

        .file-upload-zone--disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .file-upload-input {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        .file-upload-empty,
        .file-upload-selected {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: var(--spacing-sm);
          text-align: center;
        }

        .file-upload-selected {
          flex-direction: row;
          gap: var(--spacing-md);
        }

        .upload-icon {
          font-size: var(--font-size-3xl);
          line-height: 1;
        }

        .upload-text {
          font-size: var(--font-size-base);
          color: var(--color-text);
        }

        .upload-link {
          color: var(--color-primary);
          text-decoration: underline;
          font-weight: 500;
        }

        .upload-hint {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
        }

        .file-info {
          display: flex;
          flex-direction: column;
          align-items: flex-start;
          gap: var(--spacing-xs);
        }

        .file-name {
          font-weight: 600;
          color: var(--color-text);
          word-break: break-all;
        }

        .file-size {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
        }

        .file-clear-btn {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 32px;
          height: 32px;
          padding: 0;
          border: none;
          border-radius: var(--radius-full);
          background-color: var(--color-border);
          color: var(--color-text);
          cursor: pointer;
          transition: background-color var(--transition-fast);
        }

        .file-clear-btn:hover {
          background-color: var(--color-error);
          color: var(--color-text-light);
        }

        .file-upload-error {
          padding: var(--spacing-sm) var(--spacing-md);
          background-color: rgba(219, 76, 64, 0.1);
          border-radius: var(--radius-sm);
          color: var(--color-error);
          font-size: var(--font-size-sm);
        }

        .file-upload-meta {
          display: flex;
          justify-content: flex-end;
        }

        .max-size-indicator {
          font-size: var(--font-size-xs);
          color: var(--color-text-secondary);
        }

.ids-selector {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-md);
        }

        .ids-selector-label {
          font-size: var(--font-size-base);
          font-weight: 600;
          color: var(--color-text);
        }

        .ids-options {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-sm);
        }

        @media (min-width: 768px) {
          .ids-options {
            flex-direction: row;
            gap: var(--spacing-md);
          }
        }

        .ids-option {
          display: flex;
          align-items: flex-start;
          gap: var(--spacing-sm);
          padding: var(--spacing-md);
          border: 2px solid var(--color-border);
          border-radius: var(--radius-md);
          background-color: var(--color-surface);
          cursor: pointer;
          transition: border-color var(--transition-fast),
            background-color var(--transition-fast);
          flex: 1;
        }

        .ids-option:hover:not(.ids-option--disabled) {
          border-color: var(--color-primary);
          background-color: var(--color-hover);
        }

        .ids-option--selected {
          border-color: var(--color-primary);
          background-color: var(--color-hover);
        }

        .ids-option--disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .ids-option-radio {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        .ids-option-indicator {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 20px;
          height: 20px;
          min-width: 20px;
          border: 2px solid var(--color-border);
          border-radius: var(--radius-full);
          background-color: var(--color-background);
          transition: border-color var(--transition-fast),
            background-color var(--transition-fast);
          margin-top: 2px;
        }

        .ids-option-radio:checked + .ids-option-indicator {
          border-color: var(--color-primary);
          background-color: var(--color-primary);
        }

        .ids-option-radio:checked + .ids-option-indicator::after {
          content: '';
          display: block;
          width: 8px;
          height: 8px;
          border-radius: var(--radius-full);
          background-color: var(--color-text-light);
        }

        .ids-option-radio:focus-visible + .ids-option-indicator {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        .ids-option-content {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-xs);
        }

        .ids-option-label {
          font-weight: 600;
          color: var(--color-text);
          font-size: var(--font-size-base);
        }

        .ids-option-description {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
        }

        /* Custom Upload Zone */
        .ids-custom-upload {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-sm);
          margin-top: var(--spacing-sm);
          padding-left: var(--spacing-md);
          border-left: 3px solid var(--color-primary);
        }

        .ids-upload-zone {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: var(--spacing-lg);
          min-height: 100px;
          border: 2px dashed var(--color-border);
          border-radius: var(--radius-md);
          background-color: var(--color-surface);
          cursor: pointer;
          transition: border-color var(--transition-fast),
            background-color var(--transition-fast);
        }

        .ids-upload-zone:hover:not(.ids-upload-zone--disabled) {
          border-color: var(--color-primary);
          background-color: var(--color-hover);
        }

        .ids-upload-zone:focus-visible {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        .ids-upload-zone--drag-over {
          border-color: var(--color-primary);
          background-color: var(--color-active);
          border-style: solid;
        }

        .ids-upload-zone--has-file {
          border-color: var(--color-success);
          border-style: solid;
        }

        .ids-upload-zone--error {
          border-color: var(--color-error);
        }

        .ids-upload-zone--disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .ids-upload-input {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        .ids-upload-empty,
        .ids-upload-selected {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: var(--spacing-xs);
          text-align: center;
        }

        .ids-upload-selected {
          flex-direction: row;
          gap: var(--spacing-md);
        }

        .ids-upload-icon {
          font-size: var(--font-size-2xl);
          line-height: 1;
        }

        .ids-upload-text {
          font-size: var(--font-size-sm);
          color: var(--color-text);
        }

        .ids-upload-link {
          color: var(--color-primary);
          text-decoration: underline;
          font-weight: 500;
        }

        .ids-upload-hint {
          font-size: var(--font-size-xs);
          color: var(--color-text-secondary);
        }

        .ids-file-info {
          display: flex;
          flex-direction: column;
          align-items: flex-start;
          gap: var(--spacing-xs);
        }

        .ids-file-name {
          font-weight: 600;
          color: var(--color-text);
          word-break: break-all;
          font-size: var(--font-size-sm);
        }

        .ids-file-size {
          font-size: var(--font-size-xs);
          color: var(--color-text-secondary);
        }

        .ids-file-clear-btn {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 28px;
          height: 28px;
          padding: 0;
          border: none;
          border-radius: var(--radius-full);
          background-color: var(--color-border);
          color: var(--color-text);
          cursor: pointer;
          transition: background-color var(--transition-fast);
        }

        .ids-file-clear-btn:hover {
          background-color: var(--color-error);
          color: var(--color-text-light);
        }

        .ids-upload-error {
          padding: var(--spacing-sm) var(--spacing-md);
          background-color: rgba(219, 76, 64, 0.1);
          border-radius: var(--radius-sm);
          color: var(--color-error);
          font-size: var(--font-size-sm);
        }

.results-summary {
          background-color: var(--color-surface);
          border-radius: var(--radius-lg);
          border: 1px solid var(--color-border);
          padding: var(--spacing-lg);
          box-shadow: var(--shadow-sm);
        }

        .results-summary--success {
          border-color: var(--color-success);
          border-left: 4px solid var(--color-success);
        }

        .results-summary--failure {
          border-color: var(--color-error);
          border-left: 4px solid var(--color-error);
        }

        /* Header */
        .summary-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: var(--spacing-lg);
          flex-wrap: wrap;
          gap: var(--spacing-md);
        }

        .summary-title {
          display: flex;
          align-items: center;
          gap: var(--spacing-sm);
        }

        .summary-icon {
          font-size: var(--font-size-2xl);
          line-height: 1;
        }

        .summary-heading {
          margin: 0;
          font-size: var(--font-size-xl);
          font-weight: 600;
          color: var(--color-text);
        }

        .results-summary--success .summary-heading {
          color: var(--color-success);
        }

        .results-summary--failure .summary-heading {
          color: var(--color-error);
        }

        .summary-actions {
          display: flex;
          gap: var(--spacing-sm);
        }

        /* Download button */
        .download-btn {
          display: flex;
          align-items: center;
          gap: var(--spacing-xs);
          padding: var(--spacing-sm) var(--spacing-md);
          border: 1px solid var(--color-border);
          border-radius: var(--radius-md);
          background-color: var(--color-background);
          color: var(--color-text);
          font-size: var(--font-size-sm);
          font-weight: 500;
          cursor: pointer;
          transition: all var(--transition-fast);
        }

        .download-btn:hover {
          border-color: var(--color-primary);
          background-color: var(--color-hover);
          color: var(--color-primary);
        }

        .download-btn:focus-visible {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        .download-icon {
          font-size: var(--font-size-base);
        }

        /* Statistics cards */
        .summary-stats {
          display: flex;
          gap: var(--spacing-md);
          margin-bottom: var(--spacing-lg);
        }

        .stat-card {
          flex: 1;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: var(--spacing-md) var(--spacing-sm);
          border-radius: var(--radius-md);
          background-color: var(--color-background);
          border: 1px solid var(--color-border);
          min-width: 80px;
        }

        .stat-value {
          font-size: var(--font-size-2xl);
          font-weight: 700;
          line-height: 1.2;
          font-variant-numeric: tabular-nums;
        }

        .stat-label {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
          text-transform: uppercase;
          letter-spacing: 0.05em;
        }

        .stat-card--total {
          border-color: var(--color-border);
        }

        .stat-card--total .stat-value {
          color: var(--color-text);
        }

        .stat-card--passed {
          border-color: var(--color-success);
          background-color: rgba(68, 182, 168, 0.1);
        }

        .stat-card--passed .stat-value {
          color: var(--color-success);
        }

        .stat-card--failed {
          border-color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.1);
        }

        .stat-card--failed .stat-value {
          color: var(--color-error);
        }

        /* Details section */
        .summary-details {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-sm);
          padding-top: var(--spacing-md);
          border-top: 1px solid var(--color-border);
        }

        .detail-row {
          display: flex;
          align-items: center;
          gap: var(--spacing-sm);
          font-size: var(--font-size-sm);
        }

        .detail-label {
          color: var(--color-text-secondary);
          min-width: 140px;
          flex-shrink: 0;
        }

        .detail-value {
          color: var(--color-text);
          font-weight: 500;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }

        /* Responsive adjustments */
        @media (max-width: 600px) {
          .summary-header {
            flex-direction: column;
            align-items: stretch;
          }

          .summary-title {
            justify-content: center;
          }

          .download-btn {
            align-self: center;
          }

          .summary-stats {
            flex-direction: column;
          }

          .stat-card {
            flex-direction: row;
            justify-content: space-between;
            padding: var(--spacing-md);
          }

          .stat-value {
            font-size: var(--font-size-xl);
          }

          .stat-label {
            order: -1;
          }

          .detail-row {
            flex-direction: column;
            align-items: flex-start;
            gap: var(--spacing-xs);
          }

          .detail-label {
            min-width: unset;
          }

          .detail-value {
            white-space: normal;
            word-break: break-all;
          }
        }

        @media (max-width: 400px) {
          .results-summary {
            padding: var(--spacing-md);
          }

          .summary-heading {
            font-size: var(--font-size-lg);
          }
        }

.validation-progress {
          display: flex;
          align-items: flex-start;
          gap: var(--spacing-md);
          padding: var(--spacing-lg);
          background-color: var(--color-surface);
          border-radius: var(--radius-lg);
          border: 1px solid var(--color-border);
        }

        .validation-progress--pending {
          border-color: var(--color-warning);
          background-color: rgba(239, 189, 117, 0.1);
        }

        .validation-progress--processing {
          border-color: var(--color-primary);
          background-color: rgba(68, 182, 168, 0.1);
        }

        .validation-progress--completed {
          border-color: var(--color-success);
          background-color: rgba(68, 182, 168, 0.15);
        }

        .validation-progress--failed {
          border-color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.1);
        }

        /* Progress indicator (spinner or icon) */
        .progress-indicator {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 48px;
          height: 48px;
          min-width: 48px;
        }

        /* Spinner animation */
        .progress-spinner {
          position: relative;
          width: 40px;
          height: 40px;
        }

        .spinner-ring {
          position: absolute;
          width: 100%;
          height: 100%;
          border: 4px solid var(--color-border);
          border-top-color: var(--color-primary);
          border-radius: var(--radius-full);
          animation: spin 1s linear infinite;
        }

        .validation-progress--pending .spinner-ring {
          border-top-color: var(--color-warning);
        }

        @keyframes spin {
          0% {
            transform: rotate(0deg);
          }
          100% {
            transform: rotate(360deg);
          }
        }

        /* Status icon (for completed/failed states) */
        .progress-icon {
          font-size: var(--font-size-2xl);
          line-height: 1;
        }

        /* Content area */
        .progress-content {
          flex: 1;
          display: flex;
          flex-direction: column;
          gap: var(--spacing-xs);
          min-width: 0;
        }

        /* Status line with label and elapsed time */
        .progress-status {
          display: flex;
          align-items: center;
          gap: var(--spacing-md);
          flex-wrap: wrap;
        }

        .status-label {
          font-size: var(--font-size-lg);
          font-weight: 600;
          color: var(--color-text);
        }

        .validation-progress--pending .status-label {
          color: var(--color-warning-dark, #c99a40);
        }

        .validation-progress--processing .status-label {
          color: var(--color-primary);
        }

        .validation-progress--completed .status-label {
          color: var(--color-success);
        }

        .validation-progress--failed .status-label {
          color: var(--color-error);
        }

        /* Elapsed time */
        .elapsed-time {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
          padding: var(--spacing-xs) var(--spacing-sm);
          background-color: var(--color-background);
          border-radius: var(--radius-sm);
          font-variant-numeric: tabular-nums;
        }

        /* Progress message from API */
        .progress-message {
          font-size: var(--font-size-base);
          color: var(--color-text);
          padding: var(--spacing-sm) var(--spacing-md);
          background-color: var(--color-background);
          border-radius: var(--radius-sm);
          border-left: 3px solid var(--color-primary);
        }

        .validation-progress--pending .progress-message {
          border-left-color: var(--color-warning);
        }

        /* Hint text */
        .progress-hint {
          font-size: var(--font-size-sm);
          color: var(--color-text-secondary);
          font-style: italic;
        }

        /* Cancel button */
        .progress-cancel-btn {
          padding: var(--spacing-sm) var(--spacing-md);
          border: 1px solid var(--color-border);
          border-radius: var(--radius-md);
          background-color: var(--color-surface);
          color: var(--color-text-secondary);
          font-size: var(--font-size-sm);
          font-weight: 500;
          cursor: pointer;
          transition: all var(--transition-fast);
          white-space: nowrap;
        }

        .progress-cancel-btn:hover {
          border-color: var(--color-error);
          color: var(--color-error);
          background-color: rgba(219, 76, 64, 0.1);
        }

        .progress-cancel-btn:focus-visible {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        /* Responsive adjustments */
        @media (max-width: 480px) {
          .validation-progress {
            flex-direction: column;
            align-items: stretch;
            text-align: center;
          }

          .progress-indicator {
            align-self: center;
          }

          .progress-status {
            justify-content: center;
          }

          .progress-message {
            border-left: none;
            border-top: 3px solid var(--color-primary);
          }

          .validation-progress--pending .progress-message {
            border-top-color: var(--color-warning);
          }

          .progress-cancel-btn {
            align-self: center;
          }
        }

        /* Reduced motion preference */
        @media (prefers-reduced-motion: reduce) {
          .spinner-ring {
            animation-duration: 2s;
          }
        }

